  auto SAMPLES__ = SAMPLES ? _fbb.CreateVector<::flatbuffers::Offset<ERMStmSample>>(*SAMPLES) : 0;
  auto TARGET_EPOCHS__ = TARGET_EPOCHS ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*TARGET_EPOCHS) : 0;
  auto UNITS__ = UNITS ? _fbb.CreateString(UNITS) : 0;
